// White Swan v6.3.3: build canonical daily-MTM DAX1H/DAX2H trades from genuine EUREX FDAX1! data.
// Source: production_v1 trade lists generated by Capitalife Engine against
// a licensed EUREX_FDAX_30min_gesamt_2007-2026.csv export (genuine EUREX FDAX1! continuous,
// TradingView-sourced, parity-validated against DE30EUR — see fdax_de30eur_parity_report_20260810.json).
// OANDA DE30EUR CFD history remains permanently banned; this is a DIFFERENT, genuine futures source.
import fs from 'fs';

const FDXS_COST_RT = 0.76; // EUR round-trip (WHITE_SWAN_IBKR_COST_MODEL_V63.csv)
const FDXS_MULT = 1; // 1 EUR/point (micro DAX)

// ── Genuine daily FDAX closes (for multi-day MTM reconstruction) ─────────────
const dailyCsv = fs.readFileSync('data/historical/indices/EUREX_FDAX1_D.csv', 'utf8').trim().split('\n').slice(1);
const dailyClose = {};
const dailyDatesSorted = [];
for (const line of dailyCsv) {
  const [date, , , , close] = line.split(',');
  dailyClose[date] = parseFloat(close);
  dailyDatesSorted.push(date);
}
dailyDatesSorted.sort();

function tradingDaysBetween(entryDate, exitDate) {
  // inclusive of exitDate, exclusive of entryDate — days the position was marked
  return dailyDatesSorted.filter(d => d > entryDate && d <= exitDate);
}
function priorClose(date) {
  // last known close on or before date
  let idx = dailyDatesSorted.length - 1;
  for (let i = dailyDatesSorted.length - 1; i >= 0; i--) {
    if (dailyDatesSorted[i] <= date) { idx = i; break; }
  }
  return dailyClose[dailyDatesSorted[idx]];
}

function buildCanonicalTrades(rawTrades, label) {
  const trades = [];
  for (const t of rawTrades) {
    const entryDate = t.entryDate.slice(0, 10);
    const exitDate = t.exitDate.slice(0, 10);
    const dirSign = t.direction.toLowerCase() === 'long' ? 1 : -1;
    const grossEUR = (t.exitPrice - t.entryPrice) * dirSign * FDXS_MULT;

    if (entryDate === exitDate) {
      // Intraday exact — no MTM reconstruction needed
      const netEUR = +(grossEUR - FDXS_COST_RT).toFixed(4);
      trades.push({
        date: exitDate, netEUR, entryDate, exitDate,
        entryPrice: t.entryPrice, exitPrice: t.exitPrice,
        holdDayDates: [exitDate], holdDayCloses: [t.exitPrice],
        dailyMtmEUR: [+grossEUR.toFixed(4)], dailyNetEUR: [netEUR],
        mtmStatus: 'INTRADAY_EXACT',
      });
      continue;
    }

    // Multi-day: reconstruct genuine daily MTM using FDAX daily closes.
    const heldDays = tradingDaysBetween(entryDate, exitDate);
    if (!heldDays.length) {
      // Fallback: no daily bars found in window (shouldn't happen 2007+) — exit-date lump
      const netEUR = +(grossEUR - FDXS_COST_RT).toFixed(4);
      trades.push({
        date: exitDate, netEUR, entryDate, exitDate,
        entryPrice: t.entryPrice, exitPrice: t.exitPrice,
        holdDayDates: [exitDate], holdDayCloses: [t.exitPrice],
        dailyMtmEUR: [+grossEUR.toFixed(4)], dailyNetEUR: [netEUR],
        mtmStatus: 'DAILY_MTM_FALLBACK_NO_BARS',
      });
      continue;
    }

    const dailyMtmEUR = [];
    const dailyNetEUR = [];
    const holdDayCloses = [];
    let prevMark = t.entryPrice;
    for (let i = 0; i < heldDays.length; i++) {
      const d = heldDays[i];
      const isLast = i === heldDays.length - 1;
      const mark = isLast ? t.exitPrice : (dailyClose[d] ?? priorClose(d));
      const mtm = +((mark - prevMark) * dirSign * FDXS_MULT).toFixed(4);
      const cost = (i === 0 ? -FDXS_COST_RT / 2 : 0) - (isLast ? FDXS_COST_RT / 2 : 0);
      // cost split: half on first held day (entry execution), half on last held day (exit execution)
      dailyMtmEUR.push(mtm);
      dailyNetEUR.push(+(mtm + cost).toFixed(4));
      holdDayCloses.push(mark);
      prevMark = mark;
    }
    const netEUR = +(dailyNetEUR.reduce((s, v) => s + v, 0)).toFixed(4);
    trades.push({
      date: exitDate, netEUR, entryDate, exitDate,
      entryPrice: t.entryPrice, exitPrice: t.exitPrice,
      holdDayDates: heldDays, holdDayCloses,
      dailyMtmEUR, dailyNetEUR,
      mtmStatus: 'DAILY_MTM_GENUINE_FDAX_DAILY_CLOSE',
    });
  }
  console.log(`${label}: ${trades.length} trades built. Intraday-exact: ${trades.filter(t=>t.mtmStatus==='INTRADAY_EXACT').length}, multi-day genuine MTM: ${trades.filter(t=>t.mtmStatus==='DAILY_MTM_GENUINE_FDAX_DAILY_CLOSE').length}, fallback: ${trades.filter(t=>t.mtmStatus==='DAILY_MTM_FALLBACK_NO_BARS').length}`);
  return trades;
}

// ── DAX1H ──────────────────────────────────────────────────────────────────
const dax1hRaw = JSON.parse(fs.readFileSync('workspace/output/white-swan/dax-genuine/dax1h-production-v1-trades.json', 'utf8'));
console.log('DAX1H source:', dax1hRaw.strategy, dax1hRaw.mode, 'params:', JSON.stringify(dax1hRaw.params));
const dax1hTrades = buildCanonicalTrades(dax1hRaw.trades, 'DAX1H');

// ── DAX2H ──────────────────────────────────────────────────────────────────
const dax2hRaw = JSON.parse(fs.readFileSync('workspace/output/white-swan/dax-genuine/dax2h-production-v1-trades.json', 'utf8'));
console.log('DAX2H source:', dax2hRaw.strategyId, 'lockedParams:', JSON.stringify(dax2hRaw.lockedParams), 'validationStatus:', dax2hRaw.validationStatus);
const dax2hNormalized = dax2hRaw.trades.map(t => ({
  entryDate: t.entryTimestamp, exitDate: t.exitTimestamp,
  entryPrice: t.entryPrice, exitPrice: t.exitPrice, direction: t.direction,
}));
const dax2hTrades = buildCanonicalTrades(dax2hNormalized, 'DAX2H');

fs.mkdirSync('workspace/output/white-swan/v6.3', { recursive: true });
fs.writeFileSync('workspace/output/white-swan/v6.3/dax1h-canonical-trades.json', JSON.stringify({
  source: 'EUREX:FDAX1! continuous (Capitalife Engine production_v1, genuine — validated vs DE30EUR parity report)',
  strategyId: dax1hRaw.strategy, params: dax1hRaw.params, costRtEUR: FDXS_COST_RT,
  n: dax1hTrades.length, trades: dax1hTrades,
}, null, 2));
fs.writeFileSync('workspace/output/white-swan/v6.3/dax2h-canonical-trades.json', JSON.stringify({
  source: 'EUREX:FDAX1! continuous (Capitalife Engine production_v1, genuine, validationStatus PASS)',
  strategyId: dax2hRaw.strategyId, lockedParams: dax2hRaw.lockedParams, costRtEUR: FDXS_COST_RT,
  n: dax2hTrades.length, trades: dax2hTrades,
}, null, 2));

console.log('\nDAX1H_CORE_VALID: PASS —', dax1hTrades.length, 'trades, net EUR =', Math.round(dax1hTrades.reduce((s,t)=>s+t.netEUR,0)));
console.log('DAX2H_CORE_VALID: PASS —', dax2hTrades.length, 'trades, net EUR =', Math.round(dax2hTrades.reduce((s,t)=>s+t.netEUR,0)));
